CREATE TABLE IF NOT EXISTS hr_payroll_period(period_id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,entity_id TEXT NOT NULL,period_code TEXT NOT NULL,start_date DATE NOT NULL,end_date DATE NOT NULL,status TEXT NOT NULL DEFAULT 'OPEN',created_by TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(organization_id,entity_id,period_code));
CREATE TABLE IF NOT EXISTS hr_compensation(employee_id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,entity_id TEXT NOT NULL,basic_monthly NUMERIC NOT NULL DEFAULT 0,allowances_monthly NUMERIC NOT NULL DEFAULT 0,deductions_monthly NUMERIC NOT NULL DEFAULT 0,employer_cost_monthly NUMERIC NOT NULL DEFAULT 0,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS hr_payroll_run(run_id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,entity_id TEXT NOT NULL,period_id TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'DRAFT',gross_total NUMERIC NOT NULL DEFAULT 0,deduction_total NUMERIC NOT NULL DEFAULT 0,net_total NUMERIC NOT NULL DEFAULT 0,employer_cost_total NUMERIC NOT NULL DEFAULT 0,approved BOOLEAN NOT NULL DEFAULT FALSE,created_by TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS hr_payroll_line(line_id TEXT PRIMARY KEY,run_id TEXT NOT NULL,employee_id TEXT NOT NULL,attendance_hours NUMERIC NOT NULL DEFAULT 0,overtime_hours NUMERIC NOT NULL DEFAULT 0,basic NUMERIC NOT NULL DEFAULT 0,allowances NUMERIC NOT NULL DEFAULT 0,overtime_pay NUMERIC NOT NULL DEFAULT 0,deductions NUMERIC NOT NULL DEFAULT 0,gross NUMERIC NOT NULL DEFAULT 0,net NUMERIC NOT NULL DEFAULT 0,employer_cost NUMERIC NOT NULL DEFAULT 0,batch_cost_allocated NUMERIC NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS hr_payroll_batch_allocation(allocation_id TEXT PRIMARY KEY,run_id TEXT NOT NULL,employee_id TEXT NOT NULL,batch_id TEXT NOT NULL,hours NUMERIC NOT NULL,cost NUMERIC NOT NULL,created_by TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS hr_payroll_journal_boundary(journal_id TEXT PRIMARY KEY,run_id TEXT NOT NULL,organization_id TEXT NOT NULL,entity_id TEXT NOT NULL,amount NUMERIC NOT NULL,status TEXT NOT NULL DEFAULT 'READY',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(run_id));
